// The Form Trigger puts every uploaded file on ONE item, as binary keys named
// after the field label ("Transcripts_0", "Transcripts_1", ...). Fan them out
// into one item per file, and normalise the binary key to 'data' so the rest
// of the workflow does not care where the files came from.
const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    out.push({ json: { fileName: b.fileName || key, mimeType: b.mimeType || null }, binary: { data: b } });
  }
}
if (out.length === 0) {
  // Fail here, loudly, with a message a human can act on - rather than letting
  // an empty item drift downstream and blow up somewhere unhelpful.
  throw new Error('No files received. Attach the transcript .txt files to the form and submit again.');
}
out.sort((a, b) => String(a.json.fileName).localeCompare(String(b.json.fileName), undefined, { numeric: true }));
return out;

// Parse the transcript header, derive a deterministic conversation id,
// and sort every transcript by date ASCENDING before we touch Airtable.
// Ordering matters: the Candidates table holds "latest state", so an
// out-of-order write would let March overwrite July.

const MONTHS = { jan:'01', feb:'02', mar:'03', apr:'04', may:'05', jun:'06',
  jul:'07', aug:'08', sep:'09', oct:'10', nov:'11', dec:'12' };

// Accept the formats a recruiter's tooling actually emits. Anything we cannot
// parse stays null - the LLM gets a second attempt at it from the content, and
// if that fails too the transcript goes to the Review Queue rather than being
// guessed at. A wrong date silently corrupts "latest state".
const parseDate = (s) => {
  if (!s) return null;
  const t = String(s).trim();
  let m;
  // 2026-03-04
  m = t.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  // 4 March 2026 / 4th Mar 2026
  m = t.match(/(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,})\s+(\d{4})/);
  if (m && MONTHS[m[2].slice(0, 3).toLowerCase()]) {
    return m[3] + '-' + MONTHS[m[2].slice(0, 3).toLowerCase()] + '-' + String(m[1]).padStart(2, '0');
  }
  // March 4, 2026 / Mar 4 2026
  m = t.match(/([A-Za-z]{3,})\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})/);
  if (m && MONTHS[m[1].slice(0, 3).toLowerCase()]) {
    return m[3] + '-' + MONTHS[m[1].slice(0, 3).toLowerCase()] + '-' + String(m[2]).padStart(2, '0');
  }
  // 04/03/2026 - assume DD/MM (UK). Ambiguous, so flagged downstream.
  m = t.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[3] + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0');
  return null;
};

const fnv1a = (s) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36);
};

const out = [];
const all = $input.all();

for (let idx = 0; idx < all.length; idx++) {
  const item = all[idx];
  const text = String(item.json.content || '');
  const fileName = item.json.fileName || (item.binary && item.binary.data && item.binary.data.fileName) || ('transcript-' + (idx + 1) + '.txt');

  const pick = (label) => {
    const m = text.match(new RegExp('^' + label + ':\\s*(.+)$', 'mi'));
    return m ? m[1].trim() : '';
  };

  const title = pick('Title');
  const rawDate = pick('Date');
  const duration = pick('Duration');
  const participants = pick('Participants');
  const transcriptDate = parseDate(rawDate);

  // Deterministic => re-running the workflow upserts instead of duplicating.
  // Falls back to hashing the body when there is no header at all.
  const seed = (title || '') + '|' + (transcriptDate || rawDate || '') + '|' + (title ? '' : text.slice(0, 400));
  const conversationId = 'conv_' + fnv1a(seed || fileName);

  out.push({ json: { fileName, title, rawDate, transcriptDate, duration, participants, conversationId, transcript: text } });
}

// Date ASCENDING. Undated transcripts go LAST but cannot corrupt anything:
// the staleness guard in Resolve Identity compares real dates before allowing
// any overwrite of "latest state".
out.sort((a, b) => String(a.json.transcriptDate || '9999-99-99').localeCompare(String(b.json.transcriptDate || '9999-99-99')));
return out;

