// Schema-validate the LLM output BEFORE it can touch Airtable.
// Anything that fails here goes to the Review Queue, not into the base.

const raw = $input.first().json || {};
const meta = $('Loop Over Transcripts').first().json;

let data = raw.message && raw.message.content !== undefined ? raw.message.content
         : (raw.content !== undefined ? raw.content
         : (raw.output !== undefined ? raw.output : raw));

if (typeof data === 'string') {
  const cleaned = data.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { data = JSON.parse(cleaned); } catch (e) { data = null; }
}

const errors = [];
if (!data || typeof data !== 'object') errors.push('LLM did not return parseable JSON');

const cand = (data && data.candidate) || {};
const conv = (data && data.conversation) || {};

if (!cand.full_name) errors.push('Missing candidate.full_name');
if (!conv.type) errors.push('Missing conversation.type');
if (!cand.current_role && !cand.current_company) errors.push('Missing both current_role and current_company');

// A conversation with no date cannot be ordered, so it cannot safely update
// "latest state". Header parse failed AND the model could not infer one from
// the content -> a human looks at it.
const resolvedDate = conv.date || meta.transcriptDate;
if (!resolvedDate) errors.push('No conversation date could be resolved from the header or the content');

const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g, '');
const parts = String(cand.full_name || '').trim().split(/\s+/).filter(Boolean);
const firstName = cand.first_name || parts[0] || '';
const surname = cand.surname || (parts.length > 1 ? parts[parts.length - 1] : '');
if (!surname) errors.push('Could not derive a surname');

const confidence = Number(data && data.extraction_confidence != null ? data.extraction_confidence : 0);
if (confidence > 0 && confidence < 0.5) errors.push('Low extraction confidence: ' + confidence);

const result = {
  _valid: errors.length === 0,
  _errors: errors,
  conversationId: meta.conversationId,
  fileName: meta.fileName,
  title: meta.title,
  transcriptDate: resolvedDate,
  duration: meta.duration,
  participants: meta.participants,
  transcript: meta.transcript,
  firstName: firstName,
  surname: surname,
  firstNameKey: norm(firstName),
  surnameKey: norm(surname),
  confidence: confidence,
  extraction: data || {}
};
return [{ json: result }];

// ---------------------------------------------------------------------------
// IDENTITY RESOLUTION
//
// The sample data contains both failure modes on purpose:
//   * same person, two names      -> Priyanka Raghavan / Priya Raghavan
//   * two people, identical name  -> David Chen (Fentra, London, mid-market AE)
//                                    David Chen (Arden Cyber, Edinburgh, VP)
//
// The rule is NOT a score threshold. A threshold treats a quiet transcript as
// evidence of a different person, which forks a candidate every time a call is
// short or is with a client rather than the candidate.
//
// The rule is: merge on a name match UNLESS the transcript contradicts it.
//   corroboration = both sides state something and the statements agree
//   contradiction = both sides state something and the statements clash
//   silence       = neither. Silence is not evidence.
//
// Invariants:
//   1. Never silently merge two people   -> contradiction always splits + flags
//   2. Never silently split one person   -> any un-merged name match is flagged
//   3. Never decide when two records are equally plausible -> flag
// ---------------------------------------------------------------------------

const search = $input.first().json || {};
const ctx = $('Validate & Normalize').first().json;

const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g, '');
const fnv1a = (s) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36);
};
const toList = (v) => {
  if (Array.isArray(v)) return v.filter(Boolean);
  if (v === null || v === undefined || v === '') return [];
  return String(v).split(',').map((x) => x.trim()).filter(Boolean);
};

// "Nexler" and "Nexler Health" are the same employer. "Arden Cyber" and
// "Fentra" are not. Prefix tolerance both ways, min 4 chars to avoid noise.
const companyMatch = (a, b) => {
  if (!a || !b) return false;
  if (a === b) return true;
  if (a.length >= 4 && b.startsWith(a)) return true;
  if (b.length >= 4 && a.startsWith(b)) return true;
  return false;
};

// "Manchester" vs "Didsbury, Manchester" vs "Greater Manchester" all agree.
// "London" vs "Edinburgh" does not. Token overlap, not string equality.
const locTokens = (s) => String(s || '').toLowerCase().match(/[a-z]{3,}/g) || [];
const STOP_LOC = ['the', 'and', 'area', 'greater', 'city', 'centre', 'center', 'uk', 'england', 'based'];
const locOverlap = (a, b) => {
  const A = locTokens(a).filter((t) => STOP_LOC.indexOf(t) === -1);
  const B = locTokens(b).filter((t) => STOP_LOC.indexOf(t) === -1);
  if (!A.length || !B.length) return null; // silence, not disagreement
  return A.some((t) => B.indexOf(t) !== -1);
};

const cand = ctx.extraction.candidate || {};
const newCompanies = [cand.current_company].concat(toList(cand.company_history)).map(norm).filter(Boolean);
const newLoc = cand.location;
const newEdu = norm(cand.education);

const records = Array.isArray(search.records) ? search.records : [];
const assessed = [];

for (const r of records) {
  const f = r.fields || {};

  // --- name / alias --------------------------------------------------------
  const pool = [norm(f['First Name Key'])].concat(toList(f['Aliases']).map(norm)).filter(Boolean);
  let nameScore = 0;
  let exactName = false;
  for (const p of pool) {
    if (p === ctx.firstNameKey) { nameScore = Math.max(nameScore, 40); exactName = true; }
    else if (p.length >= 3 && ctx.firstNameKey.length >= 3 && (p.startsWith(ctx.firstNameKey) || ctx.firstNameKey.startsWith(p))) {
      nameScore = Math.max(nameScore, 30); // Priya <-> Priyanka
    }
  }

  const exCompanies = toList(f['Company History']).map(norm).filter(Boolean);
  const shared = exCompanies.filter((x) => newCompanies.some((y) => companyMatch(x, y)));
  const locSame = locOverlap(f['Location'], newLoc); // true | false | null
  const exEdu = norm(f['Education']);

  const corroboration = [];
  if (shared.length) corroboration.push(shared.length + ' shared employer(s)');
  if (locSame === true) corroboration.push('same location');
  if (exEdu && newEdu && exEdu === newEdu) corroboration.push('same education');

  // A contradiction requires BOTH sides to have said something.
  const contradiction = [];
  if (exCompanies.length && newCompanies.length && !shared.length) {
    contradiction.push('no employer in common');
  }
  if (locSame === false && !shared.length) {
    contradiction.push('different location with no shared employer');
  }

  const score = nameScore
    + (shared.length ? 30 : 0)
    + (shared.length >= 2 ? 20 : 0)
    + (locSame === true ? 15 : 0)
    - (contradiction.length ? 40 : 0);

  assessed.push({
    id: r.id, fields: f, nameScore, exactName, corroboration, contradiction, score,
    key: f['Candidate Key'], name: f['Full Name'], lastSeen: f['Last Conversation Date'] || null,
    aliases: toList(f['Aliases']), companyHistory: toList(f['Company History']),
  });
}

const nameMatches = assessed.filter((a) => a.nameScore > 0).sort((a, b) => b.score - a.score);
const best = nameMatches[0] || null;
const viable = nameMatches.filter((a) => a.contradiction.length === 0);

let action = 'create';
let needsReview = false;
let reason = '';
let target = null;

if (!best) {
  reason = records.length
    ? 'Surname matched ' + records.length + ' record(s), but no first name or alias is compatible'
    : 'No existing candidate with this surname';
} else if (viable.length === 0) {
  // Every name match is contradicted by the evidence -> a different human.
  action = 'create';
  needsReview = true;
  reason = 'Name matches "' + best.name + '" but the evidence contradicts it (' + best.contradiction.join('; ')
    + '). Created as a separate person - confirm or merge.';
} else if (viable.length > 1) {
  // Two plausible people, nothing to separate them. Do not guess.
  action = 'create';
  needsReview = true;
  reason = viable.length + ' existing candidates match this name and nothing in this transcript distinguishes them ('
    + viable.map((v) => v.name).join(', ') + '). Created separately - please merge manually.';
} else {
  target = viable[0];
  action = 'merge';
  if (target.corroboration.length) {
    reason = 'Merged into "' + target.name + '" - ' + target.corroboration.join('; ') + ' (score ' + target.score + ')';
  } else {
    // Name matched, nothing contradicts, but nothing corroborates either.
    // Merge (silence is not evidence) but say so out loud.
    needsReview = !target.exactName;
    reason = 'Merged into "' + target.name + '" on name alone - this transcript states nothing that corroborates or contradicts it.'
      + (target.exactName ? '' : ' Partial/alias name match, please confirm.');
  }
}

const candidateKey = action === 'merge'
  ? target.key
  : ctx.surnameKey + '-' + ctx.firstNameKey + '-' + fnv1a(ctx.surnameKey + '|' + ctx.firstNameKey + '|' + (newCompanies[0] || ''));

// Only let this transcript overwrite "latest state" if it is the newest thing
// we know. Protects against re-ingest and against an old file arriving late.
let updateState = true;
if (action === 'merge' && target.lastSeen && ctx.transcriptDate && String(target.lastSeen) > String(ctx.transcriptDate)) {
  updateState = false;
  reason += ' | Older than the last known conversation - conversation logged, profile state left alone.';
}

const resolved = {
  conversationId: ctx.conversationId,
  action, candidateKey,
  matchedRecordId: target ? target.id : null,
  score: best ? best.score : null,
  corroboration: best ? best.corroboration : [],
  contradiction: best ? best.contradiction : [],
  needsReview, reason, updateState,
  surnameMatchesConsidered: records.length,
  // carried so the payload builder can UNION rather than overwrite
  existing: target ? { fullName: target.name, aliases: target.aliases, companyHistory: target.companyHistory } : null,
};
return [{ json: resolved }];

// Turn the extraction + identity decision into Airtable upsert payloads.
// Every table upserts on a deterministic primary key, so the whole workflow
// is idempotent: run it ten times, get one set of records.

const ctx = $('Validate & Normalize').first().json;
const id = $input.first().json;
const e = ctx.extraction || {};
const c = e.candidate || {};
const conv = e.conversation || {};

const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g, '');
const slug = (s) => String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const list = (v) => (Array.isArray(v) ? v.filter(Boolean) : []);
const clean = (o) => {
  const r = {};
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (v === null || v === undefined || v === '') continue;
    if (Array.isArray(v) && v.length === 0) continue;
    r[k] = v;
  }
  return r;
};

// ---- aliases: UNION with what Airtable already holds ----------------------
// Overwriting would lose "Priyanka" the moment a "Priya" transcript merges,
// and the next "Priyanka" transcript would then fail to match.
const existing = id.existing || {};
const aliases = (existing.aliases || []).slice();
for (const n of [c.preferred_name, c.first_name, ctx.firstName]) {
  if (n && aliases.indexOf(String(n)) === -1) aliases.push(String(n));
}

// ---- Candidate ------------------------------------------------------------
// Identity fields are always written. "Latest state" fields only if this
// transcript is the newest one we have for them.
const identityFields = {
  'Candidate Key': id.candidateKey,
  'Preferred Name': c.preferred_name,
  'Surname Key': ctx.surnameKey,
  'Aliases': aliases.join(', '),
  'Needs Review': !!id.needsReview,
  'Review Reason': id.needsReview ? id.reason : '',
  'Match Score': id.score,
  'Match Signals': ['corroborates: ' + (list(id.corroboration).join(', ') || 'nothing'),
                    'contradicts: ' + (list(id.contradiction).join(', ') || 'nothing')].join(' | ')
};

// On a merge the earliest sighting stays canonical - later names become
// aliases. On a create we set them for the first time.
if (id.action === 'create') {
  identityFields['Full Name'] = c.full_name;
  identityFields['First Name Key'] = ctx.firstNameKey;
}

const stateFields = id.updateState ? {
  'Current Role': c.current_role,
  'Current Company': c.current_company,
  'Seniority': c.seniority,
  'Location': c.location,
  'Preferred Location': c.preferred_location,
  'Remote Preference': c.remote_preference,
  'Current Base': c.current_base,
  'Current OTE': c.current_ote,
  'Desired Base': c.desired_base,
  'Desired OTE': c.desired_ote,
  'Equity Importance': c.equity_importance,
  'Skills': list(c.skills),
  'Methodologies': list(c.methodologies),
  'Languages': list(c.languages),
  'Preferred Industries': list(c.preferred_industries),
  'Education': c.education,
  'Career Goal': c.career_goal,
  'Timing Constraints': c.timing_constraints,
  'Tags': list(e.tags),
  'Last Conversation Date': ctx.transcriptDate
} : {};

// Company History is cumulative and is the strongest identity signal we have,
// so it is UNIONed with Airtable rather than replaced. A transcript that only
// names the current employer must not erase the employment history.
const history = (existing.companyHistory || []).slice();
for (const n of [c.current_company].concat(list(c.company_history))) {
  if (n && history.indexOf(String(n)) === -1) history.push(String(n));
}
if (history.length) identityFields['Company History'] = history.join(', ');

const candidateFields = clean(Object.assign({}, identityFields, stateFields));
// clean() strips false, so re-assert the checkbox explicitly
candidateFields['Needs Review'] = !!id.needsReview;

// ---- Conversation (immutable log, one per transcript) ---------------------
const conversationFields = clean({
  'Conversation ID': ctx.conversationId,
  'Candidate': [id.candidateKey],
  'Title': ctx.title,
  'Date': ctx.transcriptDate,
  'Type': conv.type,
  'Source Type': conv.source_type,
  'Recruiter': conv.recruiter,
  'Participants': ctx.participants,
  'Duration': ctx.duration,
  'Summary': conv.summary,
  'Sentiment': conv.sentiment,
  'Next Action': conv.next_action,
  'Confidential': !!conv.confidential,
  'File Name': ctx.fileName,
  'Extraction Confidence': ctx.confidence,
  'Unclear': list(e.unclear).join(' | '),
  'Raw Transcript': ctx.transcript,
  // comp is a time series, not a scalar - snapshot it on the conversation
  'Base At Time': c.current_base,
  'OTE At Time': c.current_ote,
  'Desired Base At Time': c.desired_base,
  'Desired OTE At Time': c.desired_ote,
  'Role At Time': c.current_role,
  'Company At Time': c.current_company,
  'Location At Time': c.location
});
conversationFields['Confidential'] = !!conv.confidential;

// ---- Companies ------------------------------------------------------------
const companies = list(e.companies).map((x) => clean({
  'Company Name': x.name,
  'Industry': x.industry,
  'Relationship': x.relationship
})).filter((x) => x['Company Name']);

// ---- Opportunity ----------------------------------------------------------
// Keyed on candidate + COMPANY only, deliberately NOT the role text.
// T6 calls it "Enterprise Account Executive", T7's header calls it "EAE".
// Keying on role would split one process into two rows - which is exactly the
// "journey through a role" the brief is asking for. A candidate having two
// live roles at one company is rarer than a role being named two ways.
const o = e.opportunity;
const hasOpportunity = !!(o && o.company && o.role);
let opportunityFields = null;
let opportunityKey = null;
if (hasOpportunity) {
  opportunityKey = id.candidateKey + '__' + slug(o.company);
  opportunityFields = clean({
    'Opportunity Key': opportunityKey,
    'Candidate': [id.candidateKey],
    'Company Hiring': [o.company],
    'Role': o.role,
    'Stage': o.stage,
    'Status': o.status,
    'Base': o.base,
    'OTE': o.ote,
    'Equity': o.equity,
    'Recruiter Notes': o.notes,
    'Last Updated': ctx.transcriptDate
  });
}

// ---- Interviews (array) ---------------------------------------------------
// Keyed on stage + interviewer, NOT date. T6 previews the Thursday interview
// and T7 reports its outcome; only one states a date. Keying on date would
// duplicate. A single transcript can also describe several rounds (T8: Elena
// then Priyesh) - each becomes its own row.
const rawInterviews = Array.isArray(e.interview) ? e.interview : (e.interview ? [e.interview] : []);
const interviews = [];
if (hasOpportunity) {
  for (const iv of rawInterviews) {
    if (!iv || !(iv.stage || iv.interviewer || iv.feedback)) continue;
    const disc = (slug(iv.stage || '') + '-' + slug(iv.interviewer || '')).replace(/^-|-$/g, '') || slug(iv.date || ctx.transcriptDate);
    interviews.push(clean({
      'Interview Key': opportunityKey + '__' + disc,
      'Opportunity': [opportunityKey],
      'Date': iv.date || null,
      'Stage': iv.stage,
      'Interviewer': iv.interviewer,
      'Outcome': iv.outcome,
      'Strengths': iv.strengths,
      'Weaknesses': iv.weaknesses,
      'Feedback': iv.feedback,
      'Source Conversation': [ctx.conversationId]
    }));
  }
}
const hasInterviews = interviews.length > 0;

const payload = {
  candidateKey: id.candidateKey,
  candidateFields,
  conversationFields,
  companies,
  hasOpportunity,
  opportunityFields,
  hasInterviews,
  interviews
};
return [{ json: payload }];

// The OpenAI node failed after its retries. Do not stop the run - park the
// transcript in the Review Queue and carry on with the rest.
const meta = $('Loop Over Transcripts').first().json;
const err = $input.first().json || {};
const row = {
  conversationId: meta.conversationId,
  fileName: meta.fileName,
  title: meta.title,
  transcriptDate: meta.transcriptDate,
  transcript: meta.transcript,
  stage: 'Extraction',
  _errors: [String(err.error || err.message || 'OpenAI extraction failed after retries')]
};
return [{ json: row }];

// Compact, per-transcript outcome row. Feeds the end-of-run summary.
// NOTE: inside a Split In Batches loop, $('Node') returns that node's LAST
// run - which may be a previous iteration. So we verify the conversationId
// matches before trusting it.
const safe = (name) => { try { return $(name).first().json; } catch (e) { return null; } };

const meta = safe('Loop Over Transcripts') || {};
let v = safe('Validate & Normalize');
if (!v || v.conversationId !== meta.conversationId) v = null;
let r = safe('Resolve Identity');
if (!r || !v || r.conversationId !== v.conversationId) r = null;

let outcome = 'review';
if (v && v._valid && r) outcome = r.action === 'merge' ? 'updated' : 'created';

const summary = {
  file: meta.fileName || null,
  date: (v && v.transcriptDate) || meta.transcriptDate || null,
  candidate: (v && v.extraction && v.extraction.candidate && v.extraction.candidate.full_name) || null,
  outcome: outcome,
  needsReview: r ? !!r.needsReview : true,
  matchScore: r ? r.score : null,
  reason: r ? r.reason : (v && v._errors ? v._errors.join('; ') : 'Sent to review queue')
};
return [{ json: summary }];

// Silence is not success. Every run reports, pass or fail.
const rows = $input.all().map((i) => i.json);
const counts = { processed: rows.length, created: 0, updated: 0, review: 0, flagged: 0 };
for (const r of rows) {
  if (r.outcome === 'created') counts.created++;
  else if (r.outcome === 'updated') counts.updated++;
  else counts.review++;
  if (r.needsReview) counts.flagged++;
}

const lines = rows.map((r) => {
  const mark = r.outcome === 'review' ? ':x:' : (r.needsReview ? ':warning:' : ':white_check_mark:');
  return mark + ' *' + (r.candidate || 'unknown') + '* — ' + (r.file || '?') + ' (' + (r.date || '?') + ') → ' + r.outcome + (r.matchScore !== null && r.matchScore !== undefined ? ' [score ' + r.matchScore + ']' : '') + (r.reason ? '\n     _' + r.reason + '_' : '');
});

const text = [
  '*Transcript ingestion run complete*',
  counts.processed + ' processed · ' + counts.created + ' created · ' + counts.updated + ' updated · ' + counts.review + ' to review · ' + counts.flagged + ' flagged',
  '',
  lines.join('\n')
].join('\n');

const result = { counts, rows, text };
return [{ json: result }];
